To find papers with tables comparing five or more systems, I'll create a Python script that scans each Markdown file in the corpus for tables with at least five data rows (after the header separator). The script will identify relevant papers by counting rows in Markdown tables (e.g., `| System | ... |` followed by `|---|...|` and five or more data rows).

```bash
cat << 'EOF' | save_tool
import os
import re

def count_table_rows(lines):
    table_start = None
    for i, line in enumerate(lines):
        if line.strip().startswith('|'):
            table_start = i
            break
    if table_start is None:
        return 0

    separator_idx = None
    for i in range(table_start + 1, len(lines)):
        if re.match(r'^\s*\|.*\|\s*$', lines[i]):
            if re.search(r'-', lines[i]):
                separator_idx = i
                break
    if separator_idx is None:
        return 0

    data_rows = 0
    for i in range(separator_idx + 1, len(lines)):
        if lines[i].strip().startswith('|'):
            data_rows += 1
        else:
            break
    return data_rows

corpus_dir = '/corpus'
for filename in os.listdir(corpus_dir):
    if filename.endswith('.md'):
        filepath = os.path.join(corpus_dir, filename)
        with open(filepath, 'r') as f:
            lines = f.readlines()
        rows = count_table_rows(lines)
        if rows >= 5:
            print(f"Found table with >=5 rows in {filename}")
EOF
